import{_ as a,C as s,c as n,o as i,j as e,G as d,a3 as l,a as r}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"CRM reporting","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/reporting/index.md","filePath":"master/sales/crm/reporting/index.md","lastUpdated":1793789158000}'),h={name:"master/sales/crm/reporting/index.md"};function g(p,t,u,c,m,y){const o=s("ImagePopup");return i(),n("div",null,[t[0]||(t[0]=e("h1",{id:"crm-reporting",tabindex:"-1"},[r("CRM reporting "),e("a",{class:"header-anchor",href:"#crm-reporting","aria-label":'Permalink to "CRM reporting"'},"​")],-1)),t[1]||(t[1]=e("p",null,"Reporting turns your leads, opportunities and finished activities into numbers you can read and compare. You use it to plan revenue, find where deals stall, and check how busy your team is. All four reports share the same layout and controls, so you learn them once.",-1)),t[2]||(t[2]=e("blockquote",null,[e("p",null,[e("strong",null,"In simple words:"),r(" A report groups your records, adds up one number for each group, and shows the result as a list or a chart.")])],-1)),t[3]||(t[3]=e("p",null,[r("Open "),e("code",null,"CRM → Reporting"),r(". The menu holds four pages.")],-1)),d(o,{src:"/images1/crm/reporting-menu.png",alt:"CRM Reporting menu with Forecast, Pipeline, Leads and Activities"}),t[4]||(t[4]=l('<h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Built on</th><th>Views</th><th>Default measure</th><th>Default group by</th></tr></thead><tbody><tr><td><a href="./forecast.html">Forecast</a></td><td>Opportunities</td><td><strong>Board</strong>, <strong>List</strong>, <strong>Graph</strong></td><td><strong>Prorated Revenue</strong></td><td><strong>Expected Closing</strong></td></tr><tr><td><a href="./pipeline-analysis.html">Pipeline analysis</a></td><td>Opportunities</td><td><strong>List</strong>, <strong>Graph</strong></td><td><strong>Expected Revenue</strong></td><td><strong>Stage</strong></td></tr><tr><td><a href="./lead-analysis.html">Lead analysis</a></td><td>Leads and opportunities</td><td><strong>List</strong>, <strong>Graph</strong></td><td><strong>Count</strong></td><td><strong>Creation Date</strong></td></tr><tr><td><a href="./activity-analysis.html">Activity analysis</a></td><td>Finished activities</td><td><strong>List</strong>, <strong>Graph</strong></td><td><strong>Count</strong></td><td><strong>Completion Date</strong></td></tr></tbody></table><h2 id="which-report-to-use" tabindex="-1">Which report to use <a class="header-anchor" href="#which-report-to-use" aria-label="Permalink to &quot;Which report to use&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Report</th></tr></thead><tbody><tr><td>How much revenue should we expect each month?</td><td><strong>Forecast</strong></td></tr><tr><td>Where do my open deals sit, and what are they worth?</td><td><strong>Pipeline analysis</strong></td></tr><tr><td>How many leads came in, and how many did we win or lose?</td><td><strong>Lead analysis</strong></td></tr><tr><td>Which follow-ups did the team finish?</td><td><strong>Activity analysis</strong></td></tr></tbody></table><h2 id="how-every-report-works" tabindex="-1">How every report works <a class="header-anchor" href="#how-every-report-works" aria-label="Permalink to &quot;How every report works&quot;">​</a></h2><p>Each report page has the same parts.</p><ul><li><strong>View switch:</strong> Change between <strong>List</strong> and <strong>Graph</strong>. Forecast also has <strong>Board</strong>.</li><li><strong>Tabs:</strong> Ready-made views of the data, such as <strong>Open</strong>, <strong>Won</strong> or <strong>Lost</strong>.</li><li><strong>Group by:</strong> Choose the field that makes the groups, for example <strong>Stage</strong> or <strong>Salesperson</strong>.</li><li><strong>Measure:</strong> Choose the number to calculate for each group, for example <strong>Expected Revenue</strong>.</li><li><strong>Split by:</strong> Graph only. It cuts every bar into coloured parts by a second field.</li><li><strong>Filters and search:</strong> Narrow the records. Every report has <strong>Salespeople</strong> and <strong>Sales Teams</strong> filters.</li></ul><h3 id="measures" tabindex="-1">Measures <a class="header-anchor" href="#measures" aria-label="Permalink to &quot;Measures&quot;">​</a></h3><p>A measure is the number a report calculates. The sales reports share six measures.</p><table tabindex="0"><thead><tr><th>Measure</th><th>What it calculates</th></tr></thead><tbody><tr><td><strong>Count</strong></td><td>The number of records.</td></tr><tr><td><strong>Expected Revenue</strong></td><td>The sum of <strong>Expected Revenue</strong> on the records.</td></tr><tr><td><strong>Prorated Revenue</strong></td><td>The sum of expected revenue times probability. A 100,000 deal at 40% adds 40,000.</td></tr><tr><td><strong>Probability (avg.)</strong></td><td>The average of <strong>Probability</strong>, shown as a percentage.</td></tr><tr><td><strong>Days to Assign</strong></td><td>The average number of days from creation to the day a salesperson was assigned.</td></tr><tr><td><strong>Days to Close</strong></td><td>The average number of days from creation to the closed date.</td></tr></tbody></table><p>Activity analysis has only <strong>Count</strong>.</p><h3 id="the-list-view" tabindex="-1">The List view <a class="header-anchor" href="#the-list-view" aria-label="Permalink to &quot;The List view&quot;">​</a></h3><p>The list shows one row per record and an extra column for the measure you picked. At the bottom, a summary row adds up the measure for all rows. Pick a <strong>Group by</strong> and the rows fold into groups with a subtotal each.</p><h3 id="the-graph-view" tabindex="-1">The Graph view <a class="header-anchor" href="#the-graph-view" aria-label="Permalink to &quot;The Graph view&quot;">​</a></h3><p>The graph is a bar chart. Its title reads &quot;measure by group&quot;, for example <strong>Expected Revenue by Stage</strong>. Choose <strong>Measure</strong> and <strong>Split by</strong> above the chart. When you split, the bars are stacked.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The numbers depend on your data. Keep <strong>Expected Revenue</strong>, <strong>Probability</strong> and <strong>Expected Closing</strong> filled in on every opportunity. See <a href="./../pipeline/manage-opportunities.html">Manage opportunities</a>.</p></div><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>Reports only read data. Opening or changing a view never edits a record.</li><li>Forecast, Pipeline and Lead analysis read the same lead and opportunity records you see in the pipeline.</li><li>Activity analysis reads a log that Aureus writes each time an activity on a lead or opportunity is marked done.</li><li>Amounts show in the currency of your company.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../pipeline/manage-opportunities.html">Manage opportunities</a></li><li><a href="./../pipeline/mark-won-lost.html">Mark won or lost</a></li><li><a href="./../../../getting-started/search-filter-group.html">Search, filter and group records</a></li><li><a href="./../configuration/">CRM configuration</a></li></ul>',20))])}const w=a(h,[["render",g]]);export{f as __pageData,w as default};
